head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergeCol]<br/>동일값이 연속되는 Cell 이 자동으로 병합될때 대상이 되는 Body Column 의 ID 를 설정합니다.",
    "validation" : [
        "mergeCells, mergeCellsFixedCols, mergeCellsFixedRows 속성값이 'never' 가 아닌 영역에 적용됩니다.",
        "콤마(',')를 구분자로 병합이 수행될 Body Column 의 ID 를 한 개 이상 설정합니다.",
        "속성값을 설정하지 않으면 모든 Body Column 이 병합 대상이 됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // con_ 설정값 수집
    //  - con_mergeCol : '' 미설정(전체 Body Column 이 병합 대상) / col2(단일) / col2,col3(복수) / col2,col4(복수)
    let vMergeCol = con_mergeCol.getValue();

    // 병합 옵션 구성
    //  - mergeCells="bycol" 고정 : 같은 Column 내 동일값 연속 Cell 을 rowSpan(세로) 방식으로 병합
    //    (mergeCol 은 mergeCells 가 'never' 가 아닌 영역에 적용되므로 bycol 상시 활성화)
    //  - mergeCol 미설정('') 이면 mergeCol 속성 자체를 추가하지 않음(모든 Body Column 이 병합 대상)
    //  - mergeCol 설정 시 콤마로 구분된 Body Column ID 만 병합 대상이 되고,
    //    동일값이 연속되어도 비대상 컬럼은 병합되지 않음.
    let properties = {
        dataList: "data:dlt_bind",
        mergeCells: "bycol",
        defaultCellHeight: 34,
    };
    if (vMergeCol !== '') {
        properties.mergeCol = vMergeCol;
    }

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCells=bycol(세로병합), mergeCol=' + (vMergeCol === '' ? '(미설정 → 전체 Body Column 대상)' : vMergeCol) + '"', '', 'label1');

    // dataList 생성 후 세로 병합이 보이도록 여러 컬럼에 연속 동일값 구성
    //   행 | col1 | col2 | col3 | col4
    //   ---+------+------+------+------
    //    0 |  A   |  X   |  P   |  1
    //    1 |  A   |  X   |  P   |  1
    //    2 |  A   |  Y   |  P   |  2
    //    3 |  A   |  Y   |  Q   |  3
    //  · col1(A,A,A,A) : 전부 동일 → 대상이면 [행0~행3] 세로병합.
    //  · col2(X,X,Y,Y) : [행0~행1]=X / [행2~행3]=Y 두 그룹 세로병합.
    //  · col3(P,P,P,Q) : [행0~행2]=P 세로병합 (행3=Q 단독).
    //  · col4(1,1,2,3)  : [행0~행1]=1 세로병합 (행2,행3 단독).
    //  mergeCol 로 특정 컬럼만 지정하면 그 컬럼만 세로병합되고,
    //  비대상 컬럼은 동일값이 연속이어도 병합되지 않음을 확인할 수 있다.
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "A", "col2": "X", "col3": "P", "col4": "1" },
        { "col1": "A", "col2": "X", "col3": "P", "col4": "1" },
        { "col1": "A", "col2": "Y", "col3": "P", "col4": "2" },
        { "col1": "A", "col2": "Y", "col3": "Q", "col4": "3" }
    ], false);

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:380px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCol sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 병합 상태 확인 : 각 Body td 의 rowSpan 을 읽어 세로(bycol) 병합 그룹과 병합 대상 컬럼을 판정
//  - 세로 병합 : rowSpan > 1 인 td (앵커 셀)
//  - 병합이 수행된 Body Column 목록을 추출하여 mergeCol 설정 대상과 일치하는지 확인
//    · mergeCol 미설정 시 → 동일값 연속인 모든 Body Column(col1~col4) 이 병합 대상
//    · mergeCol 설정 시   → 콤마로 지정한 컬럼만 병합 대상, 비대상 컬럼은 미병합
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] mergeCells : " + target1.options.mergeCells + " / mergeCol : " + (target1.options.mergeCol === undefined ? "(미설정→전체 Column 대상)" : target1.options.mergeCol));

    // td id 는 그리드 id 기준(target1.id, 페이지 scope 시 mf_target1). e.target.id 는 클릭된 버튼 id 라 사용 불가
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let descs = [];
    let mergedColSet = {};
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (td.style.display === 'none' || getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            mergedColSet["col" + (c + 1)] = true;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let mode;
    if (rowSpanCnt === 0 && colSpanCnt === 0) mode = "never (병합 없음)";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) mode = "bycol (세로 병합)";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) mode = "byrow (가로 병합)";
    else mode = "혼합";

    bottom.setReturnValue("판정 : " + mode + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }

    // 병합 대상 컬럼이 mergeCol 설정과 일치하는지 판정 (mergeCol 고유 검증)
    let mergedCols = Object.keys(mergedColSet).sort();
    let expected;
    if (target1.options.mergeCol === undefined || target1.options.mergeCol === "") {
        // 미설정 : 동일값이 연속되는 모든 Body Column(col1~col4) 이 병합 대상
        expected = "col1,col2,col3,col4";
    } else {
        expected = target1.options.mergeCol.split(",").map(function (s) { return s.trim(); }).sort().join(",");
    }
    bottom.setReturnValue("병합된 Body Column : " + (mergedCols.length ? mergedCols.join(",") : "없음") + " / mergeCol 설정과 일치 : " + (mergedCols.join(",") === expected) + " (기대=" + expected + ")");
}
